-- SUITE-CLOCK-FLAKE-1 (2026-10-30, pillar autonomy; owner: "AUDIT AND REMEDIATE ALL FAILURE MODES AND THEIR ROOT CAUSES"). Two suites were red on CI main run b7cc5f19
-- (2026-10-27) and green locally; both sat on scripts/suite-quarantine.txt under agent_issues 5013 with "root cause open" until the entries expired on 2026-10-30.
-- Neither was a code defect; both read the wall clock twice and compared the readings:
-- 1. migrations/rem-a7-doi-sweep.test.mjs compared the rollback of world 2 with a baseline taken from world 1. world() stamps created_at and last_synced_at with datetime('now'),
--    so the two differ whenever the second turns between building them (CI: 37 passed, 1 failed). With a 1.1 s gap between the worlds the old suite failed every time. The
--    baseline is now taken from the same world, immediately before the migration.
-- 2. qnfo-fleet-control/breach-doctor-run.test.mjs made two watch ticks back to back. A run id is "breach-doctor-watch-run-<s|d>-" + Date.now() in base 36, so a second claim in the
--    same millisecond collides on cloud_ops_events.id and is reported claim-failed (CI: 89 passed, 1 failed; 6 failures in 150 native runs of the old suite, 0 in 150 of the new one).
--    The test now waits for the clock to move before its second claim; production ticks are minutes apart, so worker.js is unchanged.
-- The quarantine lines are deleted, not renewed. Detectors are code-read contracts on main: each fails if its fix is removed.
-- APPLY-BY: ci
-- DB: qnfo-audit
-- Rollback: DELETE FROM remediation_contracts WHERE class IN ('fm-suite-clock-baseline', 'fm-suite-clock-same-ms'); DELETE FROM failure_modes WHERE fm_key IN ('suite-clock-baseline', 'suite-clock-same-ms')

INSERT OR IGNORE INTO failure_modes (fm_key, failure_mode, root_cause, remediation, detector, probe_class, first_seen, issue_id, trigger_condition, symptom, blast_radius) VALUES
 ('suite-clock-baseline', 'a suite fails on CI and passes locally because it compares state stamped by two wall-clock reads', 'rem-a7-doi-sweep.test.mjs took the baseline for its rollback check from a different world than the one it rolled back; world() stamps datetime(''now'') defaults, which differ when the second turns between the two builds', 'the baseline is taken from the same world immediately before the migration (const before2 = tables(w2)); the suite passes with a 1.1 s gap between the worlds', 'code-read: migrations/rem-a7-doi-sweep.test.mjs contains const before2 = tables(w2);', 'fm-suite-clock-baseline', '2026-10-27', NULL, 'a suite builds two in-memory databases and compares a snapshot of one with a snapshot of the other', 'SUITE-RUNNER-1 reports 37 passed, 1 failed on CI, 38 passed, 0 failed on a second run; a suite-red finding that closes itself', 'every pull request and every push to main while the full set runs: a red deploy-gate for a reason outside the change'),
 ('suite-clock-same-ms', 'a suite fails on CI and passes locally because two calls land in the same millisecond', 'breach-doctor-run.test.mjs ran two watch ticks back to back; the run id is built from Date.now() in base 36, so the second claim collided on cloud_ops_events.id and was reported claim-failed', 'the test waits for the clock to move before its second claim (const nextMs); production ticks are minutes apart, so the worker is unchanged', 'code-read: qnfo-fleet-control/breach-doctor-run.test.mjs contains const nextMs = async', 'fm-suite-clock-same-ms', '2026-10-27', NULL, 'a fast worker runs two calls of code that derives an id or a key from Date.now() without an await that takes a millisecond', 'SUITE-RUNNER-1 reports 89 passed, 1 failed with error claim-failed; 6 of 150 native runs of the old suite fail on one machine', 'every pull request and every push to main while the full set runs: a red deploy-gate for a reason outside the change');

INSERT OR IGNORE INTO remediation_contracts (class, issue_id, precondition, action, verify_probe, verify_transport, max_attempts, escalate_to, expected_cadence_h, status, module, budget_ms, max_items, requires_container) VALUES
 ('fm-suite-clock-baseline', NULL, 'SUITE-CLOCK-FLAKE-1', 'failure-mode detector', '{"paths": ["migrations/rem-a7-doi-sweep.test.mjs"], "contains": "const before2 = tables(w2);"}', 'code-read', 3, 'qnfo-ops', 24, 'holding', 'failure-mode', 45000, 5, 0),
 ('fm-suite-clock-same-ms', NULL, 'SUITE-CLOCK-FLAKE-1', 'failure-mode detector', '{"paths": ["qnfo-fleet-control/breach-doctor-run.test.mjs"], "contains": "const nextMs = async"}', 'code-read', 3, 'qnfo-ops', 24, 'holding', 'failure-mode', 45000, 5, 0);
